SELECT 
FROM marketing_campaign

    AND status=#{status}
    AND owner_type=#{ownerType}
    AND (name LIKE CONCAT('%',#{keyword},'%') OR title LIKE CONCAT('%',#{keyword},'%'))

ORDER BY updated_at DESC, id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM marketing_campaign

    AND status=#{status}
    AND owner_type=#{ownerType}
    AND (name LIKE CONCAT('%',#{keyword},'%') OR title LIKE CONCAT('%',#{keyword},'%'))

SELECT 
FROM marketing_campaign
WHERE owner_type='MERCHANT' AND owner_merchant_id=#{merchantId} AND owner_store_id=#{storeId}
AND status=#{status}
ORDER BY updated_at DESC, id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM marketing_campaign
WHERE owner_type='MERCHANT' AND owner_merchant_id=#{merchantId} AND owner_store_id=#{storeId}
AND status=#{status}

