SELECT 
FROM marketing_placement p
INNER JOIN marketing_campaign c ON c.id=p.campaign_id

    AND p.position_code=#{positionCode}
    AND p.status=#{status}

ORDER BY p.sort_weight ASC, p.id ASC
LIMIT #{limit} OFFSET #{offset}

